  int selectedScreen=-1;string motionTab="缩放";
  bool ShowScreenTrack {get{return motionTab=="屏幕 3D"||Doc.ScreenMotions.Count>0;}}
  static void ResetScreenTiming(ScreenMotionClip c){c.AnimationStart=c.AnimationEnd=null;}
  void SplitScreenMotion(){if(selectedScreen<0||selectedScreen>=Doc.ScreenMotions.Count)return;var c=Doc.ScreenMotions[selectedScreen];if(position-c.Start<.05||c.End-position<.05){Status("请将播放头放在屏幕 3D 片段中间再分割。");return;}Checkpoint();double originalStart=c.AnimationStart??c.Start,originalEnd=c.AnimationEnd??c.End;var next=new ScreenMotionClip {Start=position,End=c.End,Target=c.Target.Copy(),Transition=c.Transition,Return=c.Return,Easing=c.Easing,AnimationStart=originalStart,AnimationEnd=originalEnd};c.End=position;c.AnimationStart=originalStart;c.AnimationEnd=originalEnd;Doc.ScreenMotions.Insert(selectedScreen+1,next);selectedScreen++;Changed();BuildInspector();}
