   else {Note("设置整段视频的初始姿态，或添加片段制作 3D 运镜。");inspector.Children.Add(InspectorAction("plus","添加屏幕 3D 片段",AddScreenMotion));}
   Section("构图");PositionPad(target.X,target.Y,(x,y)=>{target.X=x;target.Y=y;});Slider("目标大小",.25,4,target.Scale,"×",v=>target.Scale=v);
   Section("空间姿态");TiltPad(target);InspectorDisclosure("平面旋转与透视",()=>"Z "+target.RotationZ.ToString("0.0",CultureInfo.InvariantCulture)+"° · 透视 "+target.Perspective.ToString("0.00",CultureInfo.InvariantCulture),()=>{Slider("平面旋转",-30,30,target.RotationZ,"°",v=>target.RotationZ=v);Slider("透视强度",0,2,target.Perspective,"",v=>target.Perspective=v);});
   if(clip){Section("动画时间");Number("开始 / 秒",c.Start,v=>{c.Start=EditDocument.Clamp(v,ScreenPreviousEnd(c),c.End-.05);ResetScreenTiming(c);});Number("结束 / 秒",c.End,v=>{c.End=EditDocument.Clamp(v,c.Start+.05,ScreenNextStart(c));ResetScreenTiming(c);});Slider("进入过渡",0,Math.Min(5,(c.End-c.Start)/2),Math.Min(c.Transition,(c.End-c.Start)/2)," 秒",v=>{c.Transition=v;ResetScreenTiming(c);});Slider("返回过渡",0,Math.Min(5,(c.End-c.Start)/2),Math.Min(c.Return,(c.End-c.Start)/2)," 秒",v=>{c.Return=v;ResetScreenTiming(c);});
    Buttons(new[]{"弹性","平滑","线性"},c.Easing=="spring"?"弹性":c.Easing=="smooth"?"平滑":"线性",v=>{Checkpoint();c.Easing=v=="弹性"?"spring":v=="平滑"?"smooth":"linear";Changed();BuildInspector();});
    inspector.Children.Add(UI.Button("返回屏幕初始状态",()=>{selectedScreen=-1;DrawTimeline();BuildInspector();}));inspector.Children.Add(InspectorAction("trash","删除屏幕 3D",Delete,true));
   }else{inspector.Children.Add(UI.Button("恢复屏幕初始状态",()=>{Checkpoint();Doc.ScreenBase=new ScreenMotionState {X=Doc.Style.X,Y=Doc.Style.Y};Changed();BuildInspector();}));if(Doc.ScreenMotions.Count>0){Section("已有片段");foreach(var item in Doc.ScreenMotions.OrderBy(m=>m.Start)){int index=Doc.ScreenMotions.IndexOf(item);inspector.Children.Add(UI.Button(UI.Time(item.Start)+" — "+UI.Time(item.End),()=>SelectScreenMotion(index)));}}}
  }
  double ScreenPreviousEnd(ScreenMotionClip c){return Doc.ScreenMotions.Where(m=>m!=c&&m.End<=c.Start+.0001).Select(m=>m.End).DefaultIfEmpty(0).Max();}
  double ScreenNextStart(ScreenMotionClip c){return Doc.ScreenMotions.Where(m=>m!=c&&m.Start>=c.End-.0001).Select(m=>m.Start).DefaultIfEmpty(Doc.Length).Min();}
  void AddScreenMotion(){if(Doc==null)return;double start=Math.Min(position,Math.Max(0,Doc.Length-.1));if(Doc.ScreenMotions.Any(m=>start>=m.Start&&start<m.End)){Status("播放头位于已有屏幕 3D 片段内，请移动到空白处。");return;}double end=Doc.ScreenMotions.Where(m=>m.Start>start).Select(m=>m.Start).DefaultIfEmpty(Doc.Length).Min();end=Math.Min(end,start+3);if(end-start<.05){Status("这里没有足够空间添加屏幕 3D。");return;}
   Checkpoint();var c=new ScreenMotionClip {Start=start,End=end,Transition=Math.Min(.7,(end-start)/3),Return=Math.Min(.7,(end-start)/3),Target=new ScreenMotionState {X=Doc.Style.X,Y=Doc.Style.Y,Scale=.85,RotationX=12,RotationY=-18}};Doc.ScreenMotions.Add(c);SelectScreenMotion(Doc.ScreenMotions.Count-1);Changed();BuildInspector();
  }
  void SelectScreenMotion(int index,bool redraw=true){selectedScreen=index;selectedCut=selectedZoom=selectedOverlay=-1;tab="运镜";motionTab="屏幕 3D";var c=Doc.ScreenMotions[index];Seek(c.Start+(c.End-c.Start)/2);BuildRail();BuildInspector();if(redraw)DrawTimeline();}
  void TiltPad(ScreenMotionState target){
