   var card=new System.Windows.Shapes.Path {Fill=new LinearGradientBrush((Color)ColorConverter.ConvertFromString(dark?"#393D40":"#C0C3C2"),(Color)ColorConverter.ConvertFromString(dark?"#242729":"#D1D2D1"),45),Stroke=UI.Brush(dark?"#707476":"#8F9291"),StrokeThickness=.8,IsHitTestVisible=false};pad.Children.Add(card);
   foreach(var axis in new[]{new Line {X1=w/2,X2=w/2,Y1=inset,Y2=h-inset},new Line {X1=inset,X2=w-inset,Y1=h/2,Y2=h/2}}){axis.Stroke=UI.Brush(dark?"#35FFFFFF":"#22000000");axis.StrokeThickness=.75;axis.StrokeDashArray=new DoubleCollection {3,4};axis.IsHitTestVisible=false;pad.Children.Add(axis);}
