   var halo=new Ellipse {Width=24,Height=24,Fill=UI.Brush(dark?"#25FFFFFF":"#16000000"),IsHitTestVisible=false};var dot=new Ellipse {Width=14,Height=14,Fill=UI.Brush(dark?"#EBECEA":"#343638"),Stroke=UI.Brush(dark?"#A7AAAB":"#E0E2E1"),StrokeThickness=.75,Effect=new DropShadowEffect {BlurRadius=6,ShadowDepth=1.5,Opacity=.35},IsHitTestVisible=false};pad.Children.Add(halo);pad.Children.Add(dot);
   var xBox=UI.Pill(Window,"",60);xBox.Name="ScreenTiltX";xBox.ToolTip="X 倾斜角度（−60° 至 60°）";var yBox=UI.Pill(Window,"",60);yBox.Name="ScreenTiltY";yBox.ToolTip="Y 倾斜角度（−60° 至 60°）";inspector.Children.Add(PairedReadouts("X",xBox,"Y",yBox));
   Action draw=()=>{var r=new D.RectangleF(24,18,136,90);var projection=new ScreenProjection(r,new ScreenMotionState {RotationX=target.RotationX*.55,RotationY=target.RotationY*.55,Perspective=.72},(int)w,(int)h);var geometry=new StreamGeometry();using(var context=geometry.Open()){bool first=true;for(int corner=0;corner<4;corner++)for(int step=0;step<=8;step++){double angle=(-90+corner*90+step*90.0/8)*Math.PI/180;double cx=corner<2?r.Right-9:r.Left+9,cy=corner==0||corner==3?r.Top+9:r.Bottom-9;var p=projection.Project(cx+9*Math.Cos(angle),cy+9*Math.Sin(angle));var point=new Point(p.X,p.Y);if(first){context.BeginFigure(point,true,true);first=false;}else context.LineTo(point,true,false);}}geometry.Freeze();card.Data=geometry;double x=inset+(target.RotationY/120+.5)*(w-inset*2),y=inset+(.5-target.RotationX/120)*(h-inset*2);Canvas.SetLeft(halo,x-12);Canvas.SetTop(halo,y-12);Canvas.SetLeft(dot,x-7);Canvas.SetTop(dot,y-7);guideX.X1=guideX.X2=x;guideY.Y1=guideY.Y2=y;xBox.Text=target.RotationX.ToString("0.0",CultureInfo.InvariantCulture)+"°";yBox.Text=target.RotationY.ToString("0.0",CultureInfo.InvariantCulture)+"°";reset.IsEnabled=Math.Abs(target.RotationX)+Math.Abs(target.RotationY)>.0001;};
