  void AddScreenMotionTrack(double px){if(!ShowScreenTrack)return;for(int i=0;i<Doc.ScreenMotions.Count;i++){int index=i;var c=Doc.ScreenMotions[i];var b=new Border {Width=Math.Max(5,(c.End-c.Start)*px-3),Height=30,CornerRadius=new CornerRadius(7),Background=UI.Brush(dark?(selectedScreen==i?"#8E693C":"#514633"):(selectedScreen==i?"#E1B675":"#E8D8BD")),BorderBrush=UI.Brush(selectedScreen==i?"#9A713F":dark?"#776244":"#D5C3A5"),BorderThickness=new Thickness(selectedScreen==i?2:1),ToolTip="屏幕 3D · "+UI.Time(c.Start)+" — "+UI.Time(c.End),Child=new TextBlock {Text="过渡 "+(i+1)+" · "+UI.Time(c.End-c.Start),TextWrapping=TextWrapping.NoWrap,TextTrimming=TextTrimming.CharacterEllipsis,FontSize=10,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center,Foreground=UI.Brush(dark?"#F1E4CD":"#695537")}};Canvas.SetLeft(b,c.Start*px);Canvas.SetTop(b,156);timeline.Children.Add(b);bool moving=false,edited=false;double down=0,start=0,length=0,lo=0,hi=0;
    b.MouseLeftButtonDown+=(s,e)=>{lo=ScreenPreviousEnd(c);hi=ScreenNextStart(c);SelectScreenMotion(index,false);down=e.GetPosition(timeline).X;start=c.Start;length=c.End-c.Start;moving=true;edited=false;b.CaptureMouse();e.Handled=true;};b.MouseMove+=(s,e)=>{if(!moving)return;double delta=(e.GetPosition(timeline).X-down)/px;if(Math.Abs(delta)<.015&&!edited)return;if(!edited){Checkpoint();edited=true;}if(snap)delta=Math.Round(delta*Doc.FrameRate)/Doc.FrameRate;c.Start=EditDocument.Clamp(start+delta,lo,Math.Max(lo,hi-length));c.End=c.Start+length;ResetScreenTiming(c);Canvas.SetLeft(b,c.Start*px);RefreshPreview();};b.MouseLeftButtonUp+=(s,e)=>{moving=false;b.ReleaseMouseCapture();Changed();BuildInspector();e.Handled=true;};
    AddHandle(c.Start*px,156,30,d=>{c.Start=EditDocument.Clamp(c.Start+d,ScreenPreviousEnd(c),c.End-.05);ResetScreenTiming(c);},selectedScreen==i);AddHandle(c.End*px-5,156,30,d=>{c.End=EditDocument.Clamp(c.End+d,c.Start+.05,ScreenNextStart(c));ResetScreenTiming(c);},selectedScreen==i);
   }}
  void SetStylePosition(double x,double y){Doc.Style.X=x;Doc.Style.Y=y;if(Doc.ScreenBase!=null){Doc.ScreenBase.X=x;Doc.ScreenBase.Y=y;}}
  void DrawProjectedEffectGuide(OverlayClip o,SceneLayout layout,Pose pose,ScreenProjection projection,double left,double top){var polygon=new Polygon {Fill=Brushes.Transparent,Stroke=UI.Brush("#42987B"),StrokeThickness=1.5,Cursor=Cursors.SizeAll};var label=UI.Text(o.Name,10,"#2B5E4D");label.Background=UI.Brush("#E0F6ED");label.Padding=new Thickness(4,1,4,1);label.IsHitTestVisible=false;var grip=new Thumb {Width=12,Height=12,Background=UI.Brush("#42987B"),Cursor=Cursors.SizeNWSE};overlayGuides.Children.Add(polygon);overlayGuides.Children.Add(label);overlayGuides.Children.Add(grip);
   Action draw=()=>{var r=EffectRenderer.SourceRect(o,layout,pose);var corners=new[]{projection.Project(r.X,r.Y),projection.Project(r.Right,r.Y),projection.Project(r.Right,r.Bottom),projection.Project(r.X,r.Bottom)};polygon.Points=new PointCollection(corners.Select(p=>new Point(left+p.X,top+p.Y)));Canvas.SetLeft(label,left+corners[0].X);Canvas.SetTop(label,top+corners[0].Y);Canvas.SetLeft(grip,left+corners[2].X-6);Canvas.SetTop(grip,top+corners[2].Y-6);};draw();bool moving=false;D.PointF previous=new D.PointF();
   Func<MouseEventArgs,D.PointF> source=e=>{var p=e.GetPosition(overlayGuides);return projection.Unproject(p.X-left,p.Y-top);};polygon.MouseLeftButtonDown+=(s,e)=>{Checkpoint();moving=true;previous=source(e);polygon.CaptureMouse();e.Handled=true;};polygon.MouseMove+=(s,e)=>{if(!moving)return;var p=source(e);o.X=EditDocument.Clamp(o.X+(p.X-previous.X)/(layout.Video.Width*pose.Zoom),0,1-o.Width);o.Y=EditDocument.Clamp(o.Y+(p.Y-previous.Y)/(layout.Video.Height*pose.Zoom),0,1-o.Height);previous=p;draw();RefreshPreview();};polygon.MouseLeftButtonUp+=(s,e)=>{moving=false;polygon.ReleaseMouseCapture();Changed();BuildInspector();e.Handled=true;};
   grip.DragStarted+=(s,e)=>Checkpoint();grip.DragDelta+=(s,e)=>{var r=EffectRenderer.SourceRect(o,layout,pose);var corner=projection.Project(r.Right,r.Bottom);var p=projection.Unproject(corner.X+e.HorizontalChange,corner.Y+e.VerticalChange);o.Width=EditDocument.Clamp(o.Width+(p.X-r.Right)/(layout.Video.Width*pose.Zoom),.01,1-o.X);o.Height=EditDocument.Clamp(o.Height+(p.Y-r.Bottom)/(layout.Video.Height*pose.Zoom),.01,1-o.Y);draw();RefreshPreview();};grip.DragCompleted+=(s,e)=>{Changed();BuildInspector();};
